style.css:
@-moz-document domain("roblox.com") {
body {
        background-color: #f3f4f6 !important;
        color: #ff66cc !important;
        font-family: 'Comic Sans MS', 'Arial', sans-serif !important;
        text-align: center;
        padding: 20px;
        margin: 0;
        background-image: url('https://media.giphy.com/media/l1J9Edv2HqlzxRhvO/giphy.gif') !important;
        background-repeat: no-repeat;
        background-size: cover;
        background-position: center;
    }

    /* Rainbow Text */
    h1, h2, h3, h4, h5, h6, p {
        color: transparent;
        background-image: linear-gradient(to right, #ff0000, #ff7300, #fffb00, #4bff00, #00b0ff, #9b00ff);
        background-clip: text;
        font-size: 36px !important;
        font-weight: bold;
        animation: rainbow-text 3s infinite linear;
    }

    /* Rainbow Text Animation */
    @keyframes rainbow-text {
        0% { background-position: 0% 50%; }
        50% { background-position: 100% 50%; }
        100% { background-position: 0% 50%; }
    }

    /* Links with a furry paw print hover effect */
    a {
        color: #ff66cc !important;
        font-size: 20px !important;
        text-decoration: none;
        font-weight: bold;
        transition: color 0.3s ease, text-shadow 0.3s ease;
    }

    a:hover {
        color: #ff0000 !important;
        text-shadow: 0 0 10px #ff66cc, 0 0 20px #ff66cc;
    }

    /* Buttons with a cute fluffy effect */
    button {
        background-color: #ff66cc !important;
        color: #fff !important;
        padding: 10px 20px;
        font-size: 18px !important;
        border: 2px solid #ff00cc !important;
        border-radius: 12px;
        cursor: pointer;
        box-shadow: 0 0 10px #ff66cc;
        transition: background-color 0.3s ease, transform 0.2s ease;
    }

    button:hover {
        background-color: #ff00cc !important;
        transform: scale(1.1);
    }

    /* Fun fluffy paw print background animation */
    @keyframes paw-pulse {
        0% { transform: scale(1); }
        50% { transform: scale(1.1); }
        100% { transform: scale(1); }
    }

    .paw-print {
        background-image: url('https://media.giphy.com/media/4Zo41lhzKt6iZ8xVZF/giphy.gif');
        background-size: contain;
        background-repeat: no-repeat;
        width: 50px;
        height: 50px;
        display: inline-block;
        animation: paw-pulse 1s infinite;
    }

    /* Rainbow Border Effect */
    .rainbow-border {
        border: 5px solid;
        border-image: linear-gradient(to right, #ff0000, #ff7300, #fffb00, #4bff00, #00b0ff, #9b00ff) 1;
        padding: 10px;
    }

    /* Paws Everywhere! */
    .paw-background {
        background-image: url('https://cdn.discordapp.com/attachments/702134126915741776/855443358662246410/pawprint.gif') !important;
        background-size: 60px 60px !important;
        background-repeat: repeat !important;
    }

    /* Furry Chat Speech Bubbles */
    .chat-bubble {
        background-color: rgba(255, 255, 255, 0.8) !important;
        color: #333 !important;
        padding: 10px;
        border-radius: 20px;
        box-shadow: 0 0 10px rgba(255, 105, 180, 0.7);
        font-size: 16px !important;
    }

    .chat-bubble:after {
        content: '?' !important;
        position: absolute;
        bottom: -10px;
        left: 50%;
        transform: translateX(-50%);
    }

    /* Add a fur-tastic border effect to elements */
    .furry-border {
        border: 3px dashed #ff66cc !important;
        padding: 15px;
        box-shadow: 0 0 10px rgba(255, 105, 180, 0.8);
    }
}
